                    __boot_serial_force_puts(" ref=");
                    __boot_serial_force_putu32((uint32_t)ref);
                    __boot_serial_force_puts(" count=");
                    __boot_serial_force_puthex64((uint64_t)count);
                    __boot_serial_force_puts(" ret=");
