            __boot_serial_force_puthex64(aligned_len);
            __boot_serial_force_puts(" prot=");
            __boot_serial_force_putu32((uint32_t)prot);
            __boot_serial_force_puts(" flags=");
            __boot_serial_force_puthex64((uint64_t)(uint32_t)flags);
